\title{The Affine Structure of Sun's Truncated Legendre-Symbol Determinant}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
For a prime $p \ge 7$ with $p \equiv 3 \pmod 4$, set $m = \tfrac{p-5}{2}$ and consider the $m \times m$ matrix $A$ over the polynomial ring $\Z[X]$ defined by $A_{j,k} = X + \leg{j-k}{p}$, where $\leg{\cdot}{p}$ is the Legendre symbol regarded as an integer. Although the determinant of an $m \times m$ matrix of degree-$\le 1$ polynomials may \emph{a priori} have degree $m$ in $X$, we prove that $\det A$ is always affine, and in fact a pure degree-one monomial. We establish a fully general rank-one determinant expansion: for any commutative ring $R$, scalar $c \in R$, and $M \in \Mat_m(R)$, $\det(M + cJ) = \det M + c\sum_j \det(\rowone{M}{j})$, where $J$ is the all-ones matrix and $\mathbf{1}=(1,\dots,1)$. Specializing to $R = \Z[X]$, $c = X$ yields $\det A = \det C + (\det(C+J)-\det C)X$ with $C_{j,k}=\leg{j-k}{p}$. We then prove $C$ is antisymmetric for $p\equiv 3\pmod 4$, hence $\det C = 0$ in the odd dimension $m$, collapsing the determinant to $\det A = \det(C+J)\cdot X$. Computation confirms $\det(C+J) = \lfloor\tfrac{p-2}{3}\rfloor^{2}$ for $p = 7,11,19$, giving $\det A = \lfloor\tfrac{p-2}{3}\rfloor^{2} X$, in agreement with Sun's conjectured value. We isolate the remaining scalar $\det(C+J)$ as a focused Gauss-sum problem and outline four generalizations.
\end{abstract}

\noindent\textbf{Keywords:} Legendre symbol, quadratic residues, determinant, rank-one perturbation, antisymmetric matrix, multilinear expansion, Gauss sums, Toeplitz/circulant matrices.

\section{Introduction}

Determinants of matrices built from Legendre symbols repeatedly collapse to clean arithmetic quantities, despite being assembled from the irregular distribution of quadratic residues. Zhi-Wei Sun has compiled a large catalogue of such evaluations. We treat one entry of \emph{Toeplitz} type: a matrix indexed by a difference of coordinates, shifted by a polynomial background variable.

Fix a prime $p \ge 7$ with $p \equiv 3 \pmod 4$. Let
\[
m = \frac{p-5}{2}, \qquad C \in \Mat_m(\Z),\quad C_{j,k} = \leg{j-k}{p},
\]
the \emph{truncated Legendre-difference matrix}, and form its polynomial deformation
\[
A \in \Mat_m(\Z[X]), \qquad A_{j,k} = X + \leg{j-k}{p}.
\]
The target identity, \emph{Sun's truncated determinant identity}, is
\[
\boxed{\;\det A = \left\lfloor\frac{p-2}{3}\right\rfloor^{2}\,X.\;}
\]
Here $\lfloor\cdot\rfloor$ is the integer (floor) division performed over $\mathbb{N}$ in the formalization; the coefficient sequence over $p = 7, 11, 19, 23, 31$ is $1, 9, 25, 49, 81$, the squares of the odd numbers $1,3,5,7,9$.

Two facts are non-obvious: (i) the \emph{degree collapse}, that a determinant of degree-$\le 1$ entries (potentially degree $m$) has degree exactly $1$; and (ii) the \emph{vanishing constant term}, that $\det A$ is a monomial $cX$, not a general affine $cX+d$. The degree collapse is pure multilinear algebra valid for any base matrix (Theorem~\ref{thm:rankone}). The vanishing constant term follows from antisymmetry of $C$, holding precisely because $p \equiv 3\pmod 4$ (Theorem~\ref{thm:detC}). The remaining scalar $\det(C+J)$ is evaluated computationally and conjectured in general (Section~\ref{sec:coeff}).

\paragraph{Summary of formal results.}
\begin{center}
\begin{tabular}{ll}
\toprule
Name & Statement (informal) \\
\midrule
\texttt{det\_add\_smul\_onesM} & $\det(M + cJ) = \det M + c\sum_j \det(\rowone{M}{j})$ \\
\texttt{det\_add\_onesM} & $\det(M + J) = \det M + \sum_j \det(\rowone{M}{j})$ \\
\texttt{det\_Apoly} & $\det A = C(\det M) + C(\det(M+J)-\det M)\,X$ \\
\texttt{det\_Cleg\_eq\_zero} & $\det C = 0$ for $p\equiv 3\pmod 4$ \\
\texttt{det\_legendre\_matrix} & reduction of Sun's identity to $\det(C+J)$ \\
\bottomrule
\end{tabular}
\end{center}

\section{Preliminaries}

\subsection{The Legendre symbol}
For an odd prime $p$ and $a \in \Z$, the \emph{Legendre symbol} is
\[
\leg{a}{p} =
\begin{cases}
+1 & a \not\equiv 0,\ a \text{ a square mod } p,\\
-1 & a \text{ a non-square mod } p,\\
0 & p \mid a.
\end{cases}
\]
It is completely multiplicative in $a$, depends only on $a \bmod p$, and satisfies the first supplement to quadratic reciprocity,
\[
\leg{-1}{p} = (-1)^{(p-1)/2} = \begin{cases} +1 & p \equiv 1 \pmod 4,\\ -1 & p \equiv 3 \pmod 4. \end{cases}
\]
We regard $\leg{a}{p}$ as an integer in $\{-1,0,1\}$.

\subsection{All-ones matrix and row updates}
Over a commutative ring $R$, let $J = J_m \in \Mat_m(R)$ be the \emph{all-ones matrix}, $J_{i,k}=1$ (the Lean \texttt{onesM}). For a matrix $M$, index $j$, vector $v$, write $M[\text{row }j\leftarrow v]$ for $M$ with its $j$-th row replaced by $v$ (Lean \texttt{Matrix.updateRow}); abbreviate $\rowone{M}{j}$ with $\mathbf 1=(1,\dots,1)$.

\subsection{The deformed Legendre matrix}
For $M \in \Mat_m(\Z)$ define $\mathrm{Apoly}(M) \in \Mat_m(\Z[X])$ by $\mathrm{Apoly}(M)_{j,k} = \iota(M_{j,k}) + X$, where $\iota:\Z\hookrightarrow\Z[X]$ is the constant inclusion (Lean \texttt{Polynomial.C}). With $M = C$, $\mathrm{Apoly}(C)=A$. Note $\mathrm{Apoly}(M)=\iota_*(M) + X J$.

\section{The rank-one determinant expansion}

\begin{theorem}[Scalar rank-one expansion, \texttt{det\_add\_smul\_onesM}]\label{thm:rankone}
Let $R$ be a commutative ring, $c\in R$, $M\in\Mat_m(R)$. Then
\[
\det(M + cJ) = \det M + c\sum_{j=0}^{m-1}\det\!\bigl(\rowone{M}{j}\bigr).
\]
\end{theorem}

\begin{corollary}[All-ones expansion, \texttt{det\_add\_onesM}]\label{cor:ones}
Taking $c=1$, $\det(M+J) = \det M + \sum_{j}\det(\rowone{M}{j})$.
\end{corollary}

\begin{theorem}[Affine determinant, \texttt{det\_Apoly}]\label{thm:affine}
For $M\in\Mat_m(\Z)$,
\[
\det\mathrm{Apoly}(M) = \iota(\det M) + \iota\bigl(\det(M+J)-\det M\bigr)\cdot X \in \Z[X],
\]
affine in $X$ with constant term $\det M$ and slope $\det(M+J)-\det M$.
\end{theorem}

\begin{proof}[Proof sketch of Theorem~\ref{thm:rankone}]
View $\det$ as an alternating multilinear function of the rows. Each row of $M+cJ$ is (row of $M$) $+\,c\mathbf 1$. Multilinear expansion over the $m$ rows gives a sum over subsets $s\subseteq[m]$ of rows keeping their $M$ part:
\[
\det(M+cJ) = \sum_{s\subseteq[m]} \det(B_s),\quad (B_s)_{i,k} = \begin{cases} M_{i,k}, & i\in s,\\ c, & i\notin s.\end{cases}
\]
If $|[m]\setminus s|\ge 2$, then $B_s$ has two identical rows $(c,\dots,c)$, so $\det B_s = 0$. Survivors: $s=[m]$ gives $\det M$; $s=[m]\setminus\{j\}$ gives $c\det(\rowone{M}{j})$ by row-homogeneity. Summing yields the claim.
\end{proof}

\begin{proof}[Proof sketch of Theorem~\ref{thm:affine}]
Apply Theorem~\ref{thm:rankone} over $R=\Z[X]$, $c=X$, matrix $\iota_*(M)$, using $\mathrm{Apoly}(M)=\iota_*(M)+XJ$. Since $\iota$ is a ring homomorphism it commutes with $\det$, so $\det\iota_*(M)=\iota(\det M)$ and each updated determinant is $\iota$ of an integer determinant. Corollary~\ref{cor:ones} gives $\sum_j \det(\rowone{M}{j}) = \det(M+J)-\det M$. Rearranging yields the affine form.
\end{proof}

Theorem~\ref{thm:rankone} is independent of primality, of $m$, and of the Legendre symbol: any matrix perturbed by a scalar multiple of a rank-one all-ones matrix has a determinant linear in the scalar. It is the determinantal shadow of the matrix-determinant lemma $\det(M+uv^{\mathsf T})=\det M + v^{\mathsf T}\adj(M)u$, proved here by multilinear bookkeeping.

\section{The vanishing constant term}

By Theorem~\ref{thm:affine} the constant term of $\det A$ is $\det C$.

\begin{lemma}[Antisymmetry]\label{lem:anti}
For $p\equiv 3\pmod 4$, $C^{\mathsf T} = -C$.
\end{lemma}
\begin{proof}
$C_{k,j} = \leg{k-j}{p} = \leg{-1}{p}\leg{j-k}{p} = -\leg{j-k}{p} = -C_{j,k}$. The diagonal is zero since $\leg{0}{p}=0$.
\end{proof}

\begin{theorem}[Vanishing constant term, \texttt{det\_Cleg\_eq\_zero}]\label{thm:detC}
For $p\equiv 3\pmod 4$, $p\ge 7$, the dimension $m=\tfrac{p-5}{2}$ is odd and $\det C = 0$.
\end{theorem}
\begin{proof}[Proof sketch]
From $C^{\mathsf T}=-C$ and $\det(C^{\mathsf T})=\det C$, $\det(-C)=(-1)^m\det C$, so $(1-(-1)^m)\det C=0$. For $m$ odd this is $2\det C = 0$, forcing $\det C = 0$ over $\Z$. Writing $p=4t+3$ gives $m = 2t-1$, odd.
\end{proof}

\begin{theorem}[Reduction to a single scalar, \texttt{det\_legendre\_matrix}]\label{thm:reduce}
For $p\equiv 3\pmod 4$, $p\ge 7$, $\det A = \det(C+J)\cdot X$.
\end{theorem}

The hypothesis $p\equiv 3\pmod 4$ enters twice: it makes $\leg{-1}{p}=-1$ (so $C$ is antisymmetric, not symmetric), and it makes $m$ odd (so antisymmetry forces $\det C = 0$). Both are necessary for the clean monomial.

\section{The scalar coefficient}\label{sec:coeff}

By Theorem~\ref{thm:reduce} the problem reduces to $\det(C+J)$, where $(C+J)_{j,k} = 1+\leg{j-k}{p}\in\{0,1,2\}$.

\begin{center}
\begin{tabular}{cccccc}
\toprule
$p$ & $m$ & $\det C$ & $\det(C+J)$ & $\lfloor\frac{p-2}{3}\rfloor$ & $\lfloor\frac{p-2}{3}\rfloor^2$ \\
\midrule
$7$  & $1$  & $0$ & $1$  & $1$ & $1$ \\
$11$ & $3$  & $0$ & $9$  & $3$ & $9$ \\
$19$ & $7$  & $0$ & $25$ & $5$ & $25$ \\
$23$ & $9$  & $0$ & $49$ & $7$ & $49$ \\
$31$ & $13$ & $0$ & $81$ & $9$ & $81$ \\
\bottomrule
\end{tabular}
\end{center}

The formalization verifies $p=7,11,19$ exactly, establishing $\det A = \lfloor\tfrac{p-2}{3}\rfloor^2 X$ for those primes. The slope $\det(C+J)=\sum_j\det(\rowone{C}{j})$ is a sum of $(m-1)$-minors of a circulant-like Legendre matrix, diagonalized by additive characters of $\F_p$ with eigenvalues built from Gauss sums $g(\chi)=\sum_{a\in\F_p^\times}\chi(a)\zeta_p^a$, $|g(\chi)|=\sqrt p$. Conjugate pairing of modulus-$\sqrt p$ eigenvalues explains the perfect-square shape $1,9,25,49,81$.

\section{Algorithms}
All computations are over $\Z$. (1) \emph{Legendre symbol} via Euler's criterion $a^{(p-1)/2}\bmod p$, cost $O(\log p)$. (2) \emph{Exact integer determinant} via Bareiss fraction-free elimination, cost $O(m^3)$ with exact division at each pivot. (3) \emph{Verification}: build $C$, check $\det C = 0$, compute $\det(C+J)$ by Bareiss, compare with $\lfloor\tfrac{p-2}{3}\rfloor^2$, and optionally confirm $\det A = \det(C+J)X$ symbolically over $\Z[X]$.

\section{Future directions}

\begin{conjecture}[Gauss/Jacobi-sum square]
For every prime $p\ge 7$ with $p\equiv 3\pmod 4$, $\det(C+J)=\lfloor\tfrac{p-2}{3}\rfloor^2$, with $\lfloor\tfrac{p-2}{3}\rfloor$ an explicit character-sum count over $\F_p$. The reduction \texttt{det\_legendre\_matrix} makes this a focused character-sum identity.
\end{conjecture}

\begin{conjecture}[Constant term dichotomy]
$\det C = 0$ iff $p\equiv 3\pmod 4$; for $p\equiv 1\pmod 4$, $C$ is symmetric, $\det C$ is generically nonzero, and $\det A$ has degree $\ge 2$.
\end{conjecture}

\begin{conjecture}[Eigenvalue/circulant refinement]
$C+J$ is similar to a direct sum whose nonzero spectrum is governed by Legendre Gauss sums, so $\det(C+J)$ factors as a product of $\pm\sqrt p$-type eigenvalues whose product is $\lfloor\tfrac{p-2}{3}\rfloor^2$.
\end{conjecture}

\begin{conjecture}[Generalized perturbations]
Replacing $J$ by a rank-one $uv^{\mathsf T}$ keeps $\det(\iota_*(C)+X\,uv^{\mathsf T})$ affine in $X$ with slope $v^{\mathsf T}\adj(C)u$; for special $u,v$ (e.g. $v_j=\leg{j}{p}$) the slope again has a clean closed form. The proof of Theorem~\ref{thm:rankone} used only proportionality of the perturbation rows.
\end{conjecture}

\section{Conclusion}
A determinant that should have been a dense degree-$m$ polynomial collapses to the monomial $\lfloor\tfrac{p-2}{3}\rfloor^2 X$. The rank-one expansion (Theorem~\ref{thm:rankone}), pure multilinear algebra, forces affineness; the antisymmetry of $C$ (Theorem~\ref{thm:detC}), pure quadratic-residue arithmetic special to $p\equiv 3\pmod 4$, kills the constant term. What remains is the single integer $\det(C+J)$, a perfect square governed by Gauss sums and the natural next theorem.

