function DET_INT(M[0..n-1][0..n-1]):
    sign <- 1; prev <- 1
    for i in 0 .. n-2:
        if M[i][i] == 0:
            find r > i with M[r][i] != 0; if none return 0
            swap rows i, r; sign <- -sign
        for r in i+1 .. n-1:
            for c in i+1 .. n-1:
                M[r][c] <- (M[r][c]*M[i][i] - M[r][i]*M[i][c]) / prev
        prev <- M[i][i]
    return sign * M[n-1][n-1]

